// Package cli parses csvstat arguments, prints usage, and maps outcomes to exit codes.
package cli

import (
	"errors"
	"flag"
	"fmt"
	"io"
)

const (
	exitOK    = 0
	exitUsage = 2
)

// Run executes csvstat with args (the program name excluded) and returns the process exit code.
// Diagnostics go to stderr; stdout is reserved for profile output.
func Run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("csvstat", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() { usage(stderr) }

	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return exitOK
		}
		return exitUsage
	}
	if fs.NArg() != 1 {
		fmt.Fprintln(stderr, "csvstat: expected exactly one CSV file")
		usage(stderr)
		return exitUsage
	}
	return exitOK
}

func usage(w io.Writer) {
	fmt.Fprintln(w, "usage: csvstat FILE")
}

