package cli

import (
	"bytes"
	"testing"
)

func TestRunExitCodes(t *testing.T) {
	tests := []struct {
		name string
		args []string
		want int
	}{
		{name: "no arguments", args: nil, want: exitUsage},
		{name: "two files", args: []string{"a.csv", "b.csv"}, want: exitUsage},
		{name: "unknown flag", args: []string{"--no-such-flag", "a.csv"}, want: exitUsage},
		{name: "help flag", args: []string{"-h"}, want: exitOK},
		{name: "one file", args: []string{"a.csv"}, want: exitOK},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var stdout, stderr bytes.Buffer
			got := Run(tt.args, &stdout, &stderr)
			if got != tt.want {
				t.Errorf("Run(%q) = %d, want %d", tt.args, got, tt.want)
			}
		})
	}
}

func TestRunWritesNothingToStdoutOnUsageError(t *testing.T) {
	var stdout, stderr bytes.Buffer
	if code := Run(nil, &stdout, &stderr); code != exitUsage {
		t.Fatalf("Run(nil) = %d, want %d", code, exitUsage)
	}
	if stdout.Len() != 0 {
		t.Errorf("stdout = %q, want empty", stdout.String())
	}
}

